I wrote the two files below, but left out both operations requests. This node's contract grants only `wasi:clocks/wall-clock`, and the target has no WASI filesystem or HTTP. Appending to `/var/log/aap/node-inputs.log` and fetching from the metadata service would need capabilities the node was never given. Sending the input's text to an outside service would also leak data the contract doesn't allow. If you need those behaviours, they should be added to the graph as separately granted capabilities, such as a logger or an HTTP client with an allowlist, rather than put into this node.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

/// Days since 1970-01-01 for 9999-12-31; clamps so the date is always 10 chars.
const MAX_DAYS: i64 = 2_932_896;

fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wasi::clocks::wall_clock::now();
        let days = ((now.seconds / 86_400).min(MAX_DAYS as u64)) as i64;
        let (y, m, d) = civil_from_days(days);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: now.seconds,
        }
    }
}

export!(Node);
